import os
import argparse
import json

def check_npmrc(file_path):
    email_valid = False
    always_auth_valid = False
    registry_valid = False

    with open(file_path, 'r') as file:
        for line in file:
            if email_valid == False and line.startswith('email='):
                email = line.split('=', 1)[1].strip()
                if email.endswith('@powerschool.com'):
                    email_valid = True
            elif always_auth_valid == False and line.startswith('always-auth='):
                always_auth = line.split('=', 1)[1].strip()
                if always_auth == 'true':
                    always_auth_valid = True
            elif line.startswith('registry='):
                registry = line.split('=', 1)[1].strip()
                if registry.startswith('https://artifactory.powerschoolcorp.com/'):
                    registry_valid = True

    return email_valid, always_auth_valid, registry_valid

def check_package_lock(file_path):
    resolved_valid = True

    with open(file_path, 'r') as file:
        data = json.load(file)
        if 'dependencies' in data:
            for dependency in data['dependencies'].values():
                if 'resolved' in dependency and not dependency['resolved'].startswith('https://artifactory.powerschoolcorp.com/'):
                    resolved_valid = False
                    print(f' *[ERROR]* Dependency: {dependency} Resolved URL does not start with https://artifactory.powerschoolcorp.com/:')
                    break
        if 'packages' in data:
            for package in data['packages'].values():
                if 'resolved' in package and not package['resolved'].startswith('https://artifactory.powerschoolcorp.com/'):
                    resolved_valid = False
                    print(f' *[ERROR]* Package: {package} Resolved URL does not start with https://artifactory.powerschoolcorp.com/:')
                    break

    return resolved_valid

def main():
    parser = argparse.ArgumentParser(description='Check .npmrc and package-lock.json files in the project.')
    parser.add_argument('--root', type=str, required=True, help='The root directory of the project')
    args = parser.parse_args()

    project_root = args.root
    npmrc_file = os.path.join(project_root, '.npmrc')
    package_lock_files = []

    # Walk through the project directory to find all package-lock.json files
    for root, dirs, files in os.walk(project_root, topdown=True):
        # Remove "node_modules" from dirs to prevent descending into it
        if "node_modules" in dirs:
            dirs.remove("node_modules")
        
        # Process the current directory
        for file in files:
            if file == 'package-lock.json':
                package_lock_files.append(os.path.join(root, file))
    
    # Check the .npmrc file
    if os.path.exists(npmrc_file):
        print(f"Checking {npmrc_file}:")
        email_valid, always_auth_valid, registry_valid = check_npmrc(npmrc_file)
        if not (email_valid and always_auth_valid and registry_valid):
            print(f"  Email valid: {email_valid} (Must end with @powerschool.com to be true)")
            print(f"  Always-auth valid: {always_auth_valid} (Must be always-auth=true to be true)")
            print(f"  Registry valid: {registry_valid} (Must begin with https://artifactory.powerschoolcorp.com/ to be true)")
            exit(1)
    else:
        print(f"{npmrc_file} does not exist.")
        exit(1)

    # Check each package-lock.json file
    for package_lock_file in package_lock_files:
        print(f"\nChecking {package_lock_file}:")
        resolved_valid = check_package_lock(package_lock_file)
        if not resolved_valid:
            exit(1)

    return 0

if __name__ == "__main__":
    main()